css:
.note-to-mp {font-family: sans-serif;font-size:16px;line-height:1.9;color:#242b32;padding:12px;}
    h1 {font-size:26px;line-height:1.4;margin:24px 0;color:#28745e;}
    h2 {font-size:21px;margin:28px 0 14px;border-bottom:2px solid #28745e;padding-bottom:8px;}
    h3 {font-size:18px;margin:22px 0 10px;color:#28745e;}
    p {margin:12px 0;} blockquote {margin:18px 0;padding:12px 16px;border-left:3px solid #28745e;background:#f4f6f7;}
    pre {padding:14px;background:#f1f3f5;font-size:13px;white-space:pre-wrap;word-break:break-all;}
    a {color:#28745e;text-decoration:underline;} th,td {border:1px solid #d9dee3;padding:8px;}
    th {background:#f1f3f5;} hr {border:0;border-top:1px solid #d9dee3;margin:24px 0;}
